import {archiveFrame} from './archive-ui-art.mjs';
import meta from '../assets/passives/passive-meta-v1.json' with {type:'json'};
import {PASSIVES,PASSIVE_COSTS,normalizePassives} from './campaign-passives.mjs';
export function skillTabs(selected='active'){return `<nav class="skill-subtabs" aria-label="技能分类"><button data-skill-view="active" aria-pressed="${selected==='active'}">职业技能</button><button data-skill-view="passive" aria-pressed="${selected==='passive'}">被动技能 <small>全角色共用</small></button></nav>`;}
export function renderPassivePanel(profile){const levels=normalizePassives(profile.passives);return `<section class="passive-school"><header><small>THE SHARED ARTS</small><h3>共修 · 被动技能</h3><p>从零修习，所有英雄共享。金币强化后自动生效，无需放入F / E / R。</p></header><div class="passive-grid">${Object.entries(PASSIVES).map(([id,d])=>{const n=levels[id],r=meta.frames[d.icon].rect,s=Math.max(r[2],r[3]),x=r[0]+r[2]/2-s/2,y=r[1]+r[3]/2-s/2;return `<article class="passive-card"><i style="background-image:url('assets/passives/${meta.file}');background-size:${meta.size[0]/s*100}% ${meta.size[1]/s*100}%;background-position:${x/(meta.size[0]-s)*100}% ${y/(meta.size[1]-s)*100}%"></i><div><small>全角色共用 · ${n} / 5 级</small><h4>${d.name}</h4><p>${d.description}</p><dl><dt>${d.label}</dt><dd>${d.values[n]}${d.unit}</dd>${n<5?`<dt>下一级</dt><dd>${d.values[n+1]}${d.unit}</dd>`:''}</dl><div class="passive-ranks">${Array.from({length:5},(_,i)=>`<b class="${i<n?'lit':''}"></b>`).join('')}</div><button class="archive-primary" data-upgrade-passive="${id}" ${n>=5?'disabled':''}>${archiveFrame('upgrade')}<span>${n>=5?'已达圆满':`修习下一级 · ${PASSIVE_COSTS[n]}金币`}</span></button></div></article>`;}).join('')}</div><p class="passive-note">初始0级没有自动回血、回蓝；装备的独立属性仍正常生效。被动仅用于单机征途，不改变双人决斗。</p></section>`;}
